import{_ as a,H as n,f as e,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"03-敏感数据泄露：攻击者如何获取用户账户？","description":"","frontmatter":{},"headers":[{"level":2,"title":"敏感数据泄露","slug":"敏感数据泄露","link":"#敏感数据泄露","children":[]},{"level":2,"title":"案例实战","slug":"案例实战","link":"#案例实战","children":[{"level":3,"title":"2021 某攻防演练行动中的某集团 ERP 系统","slug":"_2021-某攻防演练行动中的某集团-erp-系统","link":"#_2021-某攻防演练行动中的某集团-erp-系统","children":[]}]},{"level":2,"title":"检测及防御方案","slug":"检测及防御方案","link":"#检测及防御方案","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web漏洞挖掘实战/03-敏感数据泄露：攻击者如何获取用户账户？.md","filePath":"Web漏洞挖掘实战/03-敏感数据泄露：攻击者如何获取用户账户？.md","lastUpdated":1795536081000}'),p={name:"Web漏洞挖掘实战/03-敏感数据泄露：攻击者如何获取用户账户？.md"};function t(l,s,o,E,r,c){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="_03-敏感数据泄露-攻击者如何获取用户账户" tabindex="-1">03-敏感数据泄露：攻击者如何获取用户账户？ <a class="header-anchor" href="#_03-敏感数据泄露-攻击者如何获取用户账户" aria-label="Permalink to &quot;03-敏感数据泄露：攻击者如何获取用户账户？&quot;">​</a></h1><p>你好，我是王昊天。</p><p>“人只要奋斗就会犯错。”</p><p>这是一个非常好的句子，出自歌德的代表作，长篇诗剧《浮士德》。</p><p>一千个读者有一千个哈姆雷特，每个人对这句话的理解都不尽相同。悲观的人或许会理解为“人努力了就要犯错误，所以就不要再努力了”；但是从我的经历看来，我更愿意相信它是在说“人努力成长本身就是试错的过程，犯错是难免的，不要因为害怕犯错而停止努力”。</p><p>为什么要提到这句话呢？因为系统如人——是有生命力的，系统随着不断更新会出现新的问题，甚至有时候问题本身就是功能设计的一部分。很多敏感数据泄露风险的源头，一部分出现在技术层，一部分出现在设计层，正如我们上面所讲，做得多了，难免会犯错。</p><h2 id="敏感数据泄露" tabindex="-1">敏感数据泄露 <a class="header-anchor" href="#敏感数据泄露" aria-label="Permalink to &quot;敏感数据泄露&quot;">​</a></h2><p>什么是敏感数据泄露呢？简单来说，如果我们的应用系统向一个未得到访问授权的用户暴露了敏感信息，那么这就是一种敏感数据泄露风险。</p><p>拓展讲一讲，设计上或者技术上有很多意外的失误会导致数据泄露。并且这种错误的严重级别分布也很宽泛，具体要取决于应用系统执行的上下文、被泄露敏感数据的类型以及攻击者从中获取的收益，这里我们列举一些数据类型。</p><p>比如个人信息分类，包括即时通讯消息、银行卡信息、交易信息、健康信息、地理位置信息以及订单信息等；系统状态信息分类，包括操作系统信息、环境变量信息、第三方包信息等；还有网络及配置信息、应用系统代码及内部状态信息、元数据信息等等。</p><p>不仅数据本身涉及分类分级，对于不同的群体而言，数据的敏感性也是不同的，每个用户群体对于数据保护有着不同的诉求。他们可能是应用系统开发者、应用系统引入的第三方数据的原始拥有者、应用系统管理员（包括业务层、应用层、系统层和运维层）、应用系统的直接用户等。</p><p>在了解数据的多样性以及使用群体的多样性之后，我们接下来看一下数据泄露方式的多样性。</p><p>首先，在代码层面可能会直接将敏感数据插入到某个消息或者资源中，这个携带着敏感数据的消息或资源被未授权的用户成功访问就会导致数据泄露。</p><p>其次，可能会由于系统内部错误直接将敏感数据插入到资源文件中，比如 Web 脚本错误泄露应用系统的全路径。</p><p>再或者，虽然在代码层面对于敏感数据有着良好的管理，但是由于编码问题，可能导致敏感数据资源被意外地展示在攻击者面前。</p><p>可以看到，敏感数据泄露并非单一的技术问题 ，它不仅具备多种风险形态，有时候更是设计层面考虑不全面导致的。</p><p>接下来我们一起来看看有哪些比较典型的风险场景：</p><ol><li>应用系统逻辑设计问题</li></ol><p>如下代码检测了用户名及密码的正确性并且给出用户结果反馈：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my $username = param(&#39;username&#39;);</span></span>
<span class="line"><span>my $password = param(&#39;password&#39;);</span></span>
<span class="line"><span>if ( IsValidUsername($username) )</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   if ( IsValidPassword($username, $password) )</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>       print &quot;Login successful&quot;;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>   else</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>       print &quot;Login failed - incorrect password&quot;;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   print &quot;Login failed - incorrect username&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上述代码中，对于不同的账户名、密码错误组合给出了不同的信息反馈，这样的设计使得潜在攻击者能够获得足够的信息来判断 login 函数的返回值，因此攻击者能够使用暴力破解的方式来遍历合法的用户名，从而可以进一步尝试暴力破解或者通过社工库撞库等方式获得对应的密码。不可否认的是，这样的设计是希望给用户提供更多友好性，但也为潜在攻击者提供了友好性，这里推荐的实现方案是如下这种：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print &quot;Login failed - incorrect username or password&quot;</span></span></code></pre></div><p>这里将错误输出设定为同一种，这样在没有丧失用户友好性的同时强化了安全性。</p><ol start="2"><li>异常处理问题如下代码尝试建立一个数据库连接，并且将 exception 输出：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">try</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   openDBConnection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} catch (Exception $e) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Caught exception:&#39;,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $e-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">getMessage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>上述代码中，如果由于网络原因（常见）或者其他原因导致 Exception 的发生，会在用户访问的页面出现 Exception 信息，这其中就可能包含数据库连接的相关信息。</p><ol start="3"><li>应用部署问题</li></ol><p>如下代码通过使用一个 Debug 标识符来进行程序执行逻辑决策：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;% if (Boolean.getBoolean(&quot;debugEnabled&quot;)) { %&gt;</span></span>
<span class="line"><span>   User account number: &lt;% =account_num %&gt;</span></span>
<span class="line"><span>&lt;% } %&gt;</span></span></code></pre></div><p>上述代码中，如果在部署应用过程中未将 debugEnabled 设置为 False，敏感的调试会被输出到用户能够访问的页面。</p><ol start="4"><li>权限获取问题</li></ol><p>如下代码为了给用户提供更符合用户需求的服务，希望通过获取坐标来判断用户的地理位置。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​uses-permission android:name=&quot;android.permission.ACCESS_FINE_LOCATION&quot;/&gt;</span></span></code></pre></div><p>在这种场景中，通过对 getLastLocation() 的调用，可以获得应用所需的坐标信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>locationClient = new LocationClient(this, this, this);</span></span>
<span class="line"><span>locationClient.connect();</span></span>
<span class="line"><span>Location userCurLocation;</span></span>
<span class="line"><span>userCurLocation = locationClient.getLastLocation();</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>事实上，为了满足应用的地理位置获取需求，ACCESS_FINE_LOCATION 这个权限有些过高了，有时候我们只需要使用 ACCESS_COARSE_LOCATION 即可满足需求。当然这里我们只是举个例子，很多应用对于权限的滥用远不止于权限颗粒度，随着法律法规的健全，应用开发过程中我们对于权限的申请和使用需要越来越谨慎。</p><h2 id="案例实战" tabindex="-1">案例实战 <a class="header-anchor" href="#案例实战" aria-label="Permalink to &quot;案例实战&quot;">​</a></h2><h3 id="_2021-某攻防演练行动中的某集团-erp-系统" tabindex="-1">2021 某攻防演练行动中的某集团 ERP 系统 <a class="header-anchor" href="#_2021-某攻防演练行动中的某集团-erp-系统" aria-label="Permalink to &quot;2021 某攻防演练行动中的某集团 ERP 系统&quot;">​</a></h3><p>该漏洞是一个由程序设计逻辑问题引发的敏感数据泄露漏洞，通过官网链接或者 URL 地址爆破，很容易找到密码找回功能界面，这里我们可以首先看一下该界面，提供了通过手机验证码来更新密码的功能：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/1.png" alt=""></a></p><p>在尝试漏洞挖掘过程中，如果能够根据返回结果的差异性来判断函数内部的执行逻辑，对攻击者而言是非常有利的信号，因为这意味着黑盒的动态测试转变为白盒测试，大幅降低了攻击难度。</p><p>因此我们首先尝试不同的输入来探测应用系统返回结果：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/2.png" alt=""></a></p><p>可以看到返回的报错信息是足够清晰的，能够帮助我们判断每一次输入的正确性，这符合我们这节课分享的第一种典型风险场景。</p><p>接下来我们需要找到真实存在的用户账号以及对应手机号码，一种可行的途径是通过社会工程学获得，另一种方式是查找公开资源。</p><p>由于公开资源的查找比较方便快捷，这里先选择该思路进行尝试，通过一些简单的查询可以找到一份该系统的使用说明视频，视频中包含了用户登录过程，虽然登录过程的密码是以星号显示的，但是用户名可以确定，并且登录之后视频中展示的账号信息配置界面包含了手机号，至此我们已经找到真正存在的用户名及手机号码：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/3.png" alt=""></a></p><p>填入正确的用户名和手机号，点击获取手机验证码，功能一切正常。接下来我们只要猜测出手机验证码即可。按照一般应用系统的设计规则，验证码的范围应该主要有两种：</p><ul><li><p>0000-9999</p></li><li><p>000000-999999</p></li></ul><p>我们先随机输入一个格式正确的验证码，并且使用 Burp 进行请求拦截，可以截获该 HTTP 请求，随后使用 Burp 的请求重放功能，将验证码部分设置为 payload，范围设置为 0000-9999，开始爆破即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/03-%25E6%2595%258F%25E6%2584%259F%25E6%2595%25B0%25E6%258D%25AE%25E6%25B3%2584%25E9%259C%25B2/4.png" alt=""></a></p><p>随着爆破结束，查看 Burp 的请求结果。结果中所有的请求结果长度都是一致的，说明并未找到正确的验证码。这里存在两种可能性，一种可能性是验证码为 6 位而非 4 位，另一种可能性是验证码已经过期。</p><p>这时我们只能逐一排查，将 payload 范围选择为 000000-999999 后重新启动重放攻击。大约3 个小时后我们终于成功爆破出正确的验证码，本次攻击的访问控制绕过部分宣告成功。</p><p>虽然本次攻击过程仅仅尝试了 6 位验证码的攻击，但是需要知道的是一般验证码的有效期大概在 10～30 分钟，本次攻击的系统并不具备该限制，但是即使未来你检测的目标系统存在该限制，你仍然可以通过多线程并发爆破的方式在有限的时间内成功碰撞出正确的验证码。</p><p>那么截止到这里，我们已经在实战中成功验证了一个典型的风险模型场景，并且该风险场景包括业务敏感数据泄露以及程序逻辑设计不当两种安全风险。</p><h2 id="检测及防御方案" tabindex="-1">检测及防御方案 <a class="header-anchor" href="#检测及防御方案" aria-label="Permalink to &quot;检测及防御方案&quot;">​</a></h2><p>由于数据泄露风险的特殊性质，主要是很多时候风险来源是逻辑层面、设计层面或者权限层面的安全问题，导致传统的防御方案和扫描器等很难发挥作用，也正因如此导致其成为了排名第一的风险种类，因此我们需要引入新型安全技术及工具来发现这类潜在风险。</p><p>在开发及设计阶段，可以考虑引入威胁建模及审计工具，来协助我们发现在逻辑层面以及设计层面引入的安全风险。通过对系统功能以及业务流程的威胁建模，可以帮助我们消除许多常见的安全隐患。</p><p>对于在开发中以及线上运营中的系统，我推荐你运用动态安全分析工具以及静态安全分析工具。以 BAS（Breach &amp; Attack Simulation Platform，自动化模拟攻击）为首的动态安全分析工具能够更全面地覆盖系统功能及接口，同时发现深层次安全问题；而以 SAST 为首的静态安全分析工具则可以从代码脆弱性角度帮助我们发现并消除一些安全隐患。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>敏感数据泄露即使在今天仍然是相当严重且普遍存在的一个风险点，主要原因是数据泄露并非一个纯粹的技术性问题，很多时候与业务流程、功能设计都息息相关。</p><p>单纯从漏洞危害程度来看，敏感数据泄露主要分为两种，一种是业务敏感数据泄露，另一种是技术敏感信息泄露。业务敏感数据的泄露危害性是巨大的，会直接影响到公司的品牌和业务运行；技术敏感信息泄露往往不能对应用系统安全性产生直接威胁，但配合其他漏洞的综合利用可以实现 1+1&gt;2 的效果，其他漏洞利用过程所需的重要信息也许就隐藏在泄露的技术敏感信息中。</p><p>这节课我们首先重点探讨了几种常见的非技术性敏感数据泄露场景：</p><ol><li><p>应用系统设计阶段逻辑问题；</p></li><li><p>异常处理输出不当；</p></li><li><p>应用部署时未关闭调试开关；</p></li><li><p>权限获取过多。</p></li></ol><p>接下来我们用一个 2021 年真实的护网行动案例，带你感受了现实场景的漏洞挖掘和利用。某世界 500 强集团的 ERP 系统，存在典型的应用系统设计阶段逻辑问题，通过输入和输出信息，攻击者可以判断出开发者的内部函数代码逻辑，进而不断探测出敏感数据，完成账户控制。</p><p>最后，针对敏感数据泄露的防御方案，我们列举了包括 BAS、SAST、威胁建模在内的几种常见的有效防御方案。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>通过本节课的探讨，你可以在实际场景中找到一个典型的潜在敏感数据泄露风险点吗？</p><p>欢迎在评论区留下你的思考，我们下节课再见。</p>`,69)])])}const g=a(p,[["render",t]]);export{d as __pageData,g as default};
